new Ext.Anim({
    is3d: true,
    direction: 'left',
    style: 'outer',
    before: function(el) {
        var origin = '0% 0%',
            fromRotate = 0,
            toRotate = 0,
            rotateProp = 'Y',
            fromZ = 0,
            toZ = 0,
            elW = el.getWidth(),
            elH = el.getHeight(),
            showTranslateZ = true,
            fromTranslate = ' translateX(0)',
            toTranslate = '';
        if (this.direction === 'left' || this.direction === 'right') {
            if (this.out) {
                origin = '100% 100%';
                toZ = elW;
                toRotate = -90;
            } else {
                origin = '0% 0%';
                fromZ = elW;
                fromRotate = 90;
            }
        } else if (this.direction === 'up' || this.direction === 'down') {
            rotateProp = 'X';
            if (this.out) {
                origin = '100% 100%';
                toZ = elH;
                toRotate = 90;
            } else {
                origin = '0% 0%';
                fromZ = elH;
                fromRotate = -90;
            }
        }
        if (this.direction === 'down' || this.direction === 'right') {
            fromRotate *= -1;
            toRotate *= -1;
            origin = (origin === '0% 0%') ? '100% 100%' : '0% 0%';
        }
        if (this.style === 'inner') {
            fromZ *= -1;
            toZ *= -1;
            fromRotate *= -1;
            toRotate *= -1;
            if (!this.out) {
                toTranslate = ' translateX(0px)';
                origin = '0% 50%';
            } else {
                toTranslate = fromTranslate;
                origin = '100% 50%';
            }
        }
        this.from = {
            '-webkit-transform': 'rotate' + rotateProp + '(' + fromRotate + 'deg)' + (showTranslateZ ? ' translateZ(' + fromZ + 'px)' : '') + fromTranslate,
            '-webkit-transform-origin': origin
        };
        this.to = {
            '-webkit-transform': 'rotate' + rotateProp + '(' + toRotate + 'deg) translateZ(' + toZ + 'px)' + toTranslate,
            '-webkit-transform-origin': origin
        };
    },
    duration: 250
})

new Ext.Anim({
    type: 'fade',
    before: function(el) {
        var fromOpacity = 1,
            toOpacity = 1,
            curZ = el.getStyle('z-index') === 'auto' ? 0 : el.getStyle('z-index'),
            zIndex = curZ;
        if (this.out) {
            toOpacity = 0;
        } else {
            zIndex = Math.abs(curZ) + 1;
            fromOpacity = 0;
        }
        this.from = {
            'opacity': fromOpacity,
            'z-index': zIndex
        };
        this.to = {
            'opacity': toOpacity,
            'z-index': zIndex
        };
    }
})

new Ext.Anim({
    is3d: true,
    direction: 'left',
    before: function() {
        var rotateProp = 'Y',
            fromScale = 1,
            toScale = 1,
            fromRotate = 0,
            toRotate = 0;
        if (this.out) {
            toRotate = -180;
            toScale = 0.8;
        } else {
            fromRotate = 180;
            fromScale = 0.8;
        }
        if (this.direction === 'up' || this.direction === 'down') {
            rotateProp = 'X';
        }
        if (this.direction === 'right' || this.direction === 'left') {
            toRotate *= -1;
            fromRotate *= -1;
        }
        this.from = {
            '-webkit-transform': 'rotate' + rotateProp + '(' + fromRotate + 'deg) scale(' + fromScale + ')',
            '-webkit-backface-visibility': 'hidden'
        };
        this.to = {
            '-webkit-transform': 'rotate' + rotateProp + '(' + toRotate + 'deg) scale(' + toScale + ')',
            '-webkit-backface-visibility': 'hidden'
        };
    }
})

new Ext.Anim({
    scaleOnExit: true,
    before: function(el) {
        var fromScale = 1,
            toScale = 1,
            fromOpacity = 1,
            toOpacity = 1,
            curZ = el.getStyle('z-index') === 'auto' ? 0 : el.getStyle('z-index'),
            fromZ = curZ,
            toZ = curZ;
        if (!this.out) {
            fromScale = 0.01;
            fromZ = curZ + 1;
            toZ = curZ + 1;
            fromOpacity = 0;
        } else {
            if (this.scaleOnExit) {
                toScale = 0.01;
                toOpacity = 0;
            } else {
                toOpacity = 0.8;
            }
        }
        this.from = {
            '-webkit-transform': 'scale(' + fromScale + ')',
            '-webkit-transform-origin': '50% 50%',
            'opacity': fromOpacity,
            'z-index': fromZ
        };
        this.to = {
            '-webkit-transform': 'scale(' + toScale + ')',
            '-webkit-transform-origin': '50% 50%',
            'opacity': toOpacity,
            'z-index': toZ
        };
    }
})

new Ext.Anim({
    direction: 'left',
    cover: false,
    reveal: false,
    opacity: false,
    'z-index': false,
    before: function(el) {
        var currentZIndex = el.getStyle('z-index') === 'auto' ? 0 : el.getStyle('z-index'),
            currentOpacity = el.getStyle('opacity'),
            zIndex = currentZIndex + 1,
            out = this.out,
            direction = this.direction,
            toX = 0,
            toY = 0,
            fromX = 0,
            fromY = 0,
            elH = el.getHeight(),
            elW = el.getWidth();
        if (direction === 'left' || direction === 'right') {
            if (out) {
                toX = -elW;
            } else {
                fromX = elW;
            }
        } else if (direction === 'up' || direction === 'down') {
            if (out) {
                toY = -elH;
            } else {
                fromY = elH;
            }
        }
        if (direction === 'right' || direction === 'down') {
            toY *= -1;
            toX *= -1;
            fromY *= -1;
            fromX *= -1;
        }
        if (this.cover && out) {
            toX = 0;
            toY = 0;
            zIndex = currentZIndex;
        } else if (this.reveal && !out) {
            fromX = 0;
            fromY = 0;
            zIndex = currentZIndex;
        }
        this.from = {
            '-webkit-transform': 'translate3d(' + fromX + 'px, ' + fromY + 'px, 0)',
            'z-index': zIndex,
            'opacity': currentOpacity - 0.01
        };
        this.to = {
            '-webkit-transform': 'translate3d(' + toX + 'px, ' + toY + 'px, 0)',
            'z-index': zIndex,
            'opacity': currentOpacity
        };
    }
})

new Ext.Anim({
    before: function(el) {
        var curZ = el.getStyle('z-index'),
            zIndex,
            mask = '';
        if (!this.out) {
            zIndex = curZ + 1;
            mask = '-webkit-gradient(linear, left bottom, right bottom, ' + 'from(transparent), to(#000), color-stop(66%, #000), color-stop(33%, ' + 'transparent))';
            this.from = {
                '-webkit-mask-image': mask,
                '-webkit-mask-size': el.getWidth() * 3 + 'px ' + el.getHeight() + 'px',
                'z-index': zIndex,
                '-webkit-mask-position-x': 0
            };
            this.to = {
                '-webkit-mask-image': mask,
                '-webkit-mask-size': el.getWidth() * 3 + 'px ' + el.getHeight() + 'px',
                'z-index': zIndex,
                '-webkit-mask-position-x': -el.getWidth() * 2 + 'px'
            };
        }
    },
    duration: 500
})

items.text:
Represents an Ext JS application, which is typically a single page app using a
{@link Ext.container.Viewport Viewport}.

An application consists of one or more Views. The behavior of a View is managed by its
corresponding {@link Ext.app.ViewController} and {@link Ext.app.ViewModel}.

Global activities are coordinated by {@link Ext.app.Controller} which are
ultimately instantiated by an instance of this (or a derived) class.

    Ext.application({
        name: 'MyApp',

        // The name of the initial view to create. With the classic toolkit this class
        // will gain a "viewport" plugin if it does not extend Ext.Viewport. With the
        // modern toolkit, the main view will be added to the Viewport.
        //
        //mainView: 'Main.view.main.Main'
    });

This does several things. First it creates a global variable called 'MyApp' - all of
your Application's classes (such as its Models, Views and Controllers) will reside under
this single namespace, which drastically lowers the chances of colliding global variables.

The MyApp global will also have a getApplication method to get a reference to the current
application:

    var app = MyApp.getApplication();

# Telling Application about the rest of the app

Because an Ext.app.Application represents an entire app, we should tell it about the other
parts of the app - namely the Models, Views and Controllers that are bundled with the
application. Let's say we have a blog management app; we might have Models and Controllers for
Posts and Comments, and Views for listing, adding and editing Posts and Comments. Here's how
we'd tell our Application about all these things:

    Ext.application({
        name: 'Blog',

        models: ['Post', 'Comment'],

        controllers: ['Posts', 'Comments'],

        launch: function() {
            ...
        }
    });

Note that we didn't actually list the Views directly in the Application itself. This is because
Views are managed by Controllers, so it makes sense to keep those dependencies there.
The Application will load each of the specified Controllers using the pathing conventions
laid out in the [application architecture guide][1]
- in this case expecting the controllers to reside in app/controller/Posts.js and
app/controller/Comments.js. In turn, each Controller simply needs to list the Views it uses
and they will be automatically loaded. Here's how our Posts controller like be defined:

    Ext.define('MyApp.controller.Posts', {
        extend: 'Ext.app.Controller',
        views: ['posts.List', 'posts.Edit'],

        // the rest of the Controller here
    });

Because we told our Application about our Models and Controllers, and our Controllers about
their Views, Ext JS will automatically load all of our app files for us. This means we don't
have to manually add script tags into our html files whenever we add a new class, but more
importantly it enables us to create a minimized build of our entire application using Sencha Cmd.

# Deriving from Ext.app.Application

Typically, applications do not derive directly from Ext.app.Application. Rather, the
configuration passed to `Ext.application` mimics what you might do in a derived class.
In some cases, however, it can be desirable to share logic by using a derived class
from `{@link Ext.app.Application}`.

Derivation works as you would expect, but using the derived class should still be the
job of the `Ext.application` method.

    Ext.define('MyApp.Application', {
        extend: 'Ext.app.Application',
        name: 'MyApp',
        ...
    });

    Ext.application('MyApp.Application');

For more information about writing Ext JS applications, please see
the [application architecture guide][1].
[1]: ../guides/application_architecture/application_architecture.html

The name of a property to be assigned to the main namespace to gain a reference to
this application. Can be set to an empty value to prevent the reference from
being created

    Ext.application({
        name: 'MyApp',
        appProperty: 'myProp',

        launch: function() {
            console.log(MyApp.myProp === this);
        }
    });

A class name to use with the `Ext.application` call. The class must
also extend {@link Ext.app.Application}.

    Ext.define('MyApp.Application', {
        extend: 'Ext.app.Application',

        launch: function() {
            Ext.direct.Manager.addProvider(Ext.REMOTING_API);
        }
    });

    Ext.application({
        extend: 'MyApp.Application'
    });

The application class to be used as the main viewport view for the
application.  The view will be configured with the
{@link Ext.plugin.Viewport viewport plugin} to ensure the view takes up all
available space in the browser viewport.  The main view will be created after
the application's {@link #method!init #init} method is called and before the
{@link #method!launch #launch} method.  The main view should be an application class type and
not a class from the framework.

The main view value may be:
 - string representing the full class name of the main view or the partial class name
following "AppName.view." (provided your main view class follows that convention).
 - config object for the main view
 - main view class instance

    Ext.define('MyApp.view.main.Main', {
        extend: 'Ext.panel.Panel',
        xtype: 'mainview',
        title: 'Main Viewport View'
    });

    Ext.application({
        name : 'MyApp',

        mainView: 'MyApp.view.main.Main'
        // mainView: 'main.Main'
        // mainView: new MyApp.view.main.Main()
        // mainView: { xtype: 'mainview' }
    });

**Note:** You may also call {@link #setMainView} at runtime if you require
logic within the application's {@link #method!launch #launch} method to be processed prior to
the creation of the main view.

The list of namespace prefixes used in the application to resolve dependencies
like Views and Stores:

     Ext.application({
         name: 'MyApp',

         namespaces: ['Common.code'],

         controllers: [ 'Common.code.controller.Foo', 'Bar' ]
     });

     Ext.define('Common.code.controller.Foo', {
         extend: 'Ext.app.Controller',

         models: ['Foo'],    // Loads Common.code.model.Foo
         views:  ['Bar']     // Loads Common.code.view.Bar
     });

     Ext.define('MyApp.controller.Bar', {
         extend: 'Ext.app.Controller',

         models: ['Foo'],    // Loads MyApp.model.Foo
         views:  ['Bar']     // Loads MyApp.view.Bar
     });

You don't need to include main namespace (MyApp), it will be added to the list
automatically.

Adds listeners to components selected via {@link Ext.ComponentQuery}. Accepts an
object containing component paths mapped to a hash of listener functions.
The function value may also be a string matching the name of a method on the
controller.

In the following example the `updateUser` function is mapped to to the `click`
event on a button component, which is a child of the `useredit` component.

     Ext.define('MyApp.controller.Users', {
         extend: 'Ext.app.Controller',

         control: {
             'useredit button[action=save]': {
                 click: 'updateUser'
             }
         },

         updateUser: function(button) {
             console.log('clicked the Save button');
         }
     });

The method you pass to the listener will automatically be resolved on the controller.
In this case, the `updateUser` method that will get executed on the `button` `click`
event will resolve to the `updateUser` method on the controller,

See {@link Ext.ComponentQuery} for more information on component selectors.

Adds listeners to components selected via {@link Ext.ComponentQuery}. Accepts an
object containing component paths mapped to a hash of listener functions.

In the following example the `updateUser` function is mapped to to the `click`
event on a button component, which is a child of the `useredit` component.

     Ext.define('AM.controller.Users', {
         init: function() {
             this.control({
                 'useredit button[action=save]': {
                     click: this.updateUser
                 }
             });
         },

         updateUser: function(button) {
             console.log('clicked the Save button');
         }
     });

Or alternatively one call `control` with two arguments:

     this.control('useredit button[action=save]', {
         click: this.updateUser
     });

See {@link Ext.ComponentQuery} for more information on component selectors.

Adds listeners to different event sources (also called "event domains"). The
primary event domain is that of components, but there are also other event domains:
{@link Ext.app.domain.Global} domain that intercepts events fired from
{@link Ext.GlobalEvents} Observable instance, {@link Ext.app.domain.Controller}
domain can be used to listen to events fired by other Controllers,
{@link Ext.app.domain.Store} domain gives access to Store events, and
{@link Ext.app.domain.Direct} domain can be used with Ext Direct Providers
to listen to their events.

To listen to "bar" events fired by a controller with id="foo":

     Ext.define('AM.controller.Users', {
         init: function() {
             this.listen({
                 controller: {
                     '#foo': {
                        bar: this.onFooBar
                     }
                 }
             });
         },
         ...
     });

To listen to "bar" events fired by any controller, and "baz" events
fired by Store with storeId="baz":

     Ext.define('AM.controller.Users', {
         init: function() {
             this.listen({
                 controller: {
                     '*': {
                        bar: this.onAnyControllerBar
                     }
                 },
                 store: {
                     '#baz': {
                         baz: this.onStoreBaz
                     }
                 }
             });
         },
         ...
     });

To listen to "idle" events fired by {@link Ext.GlobalEvents} when other event
processing is complete and Ext JS is about to return control to the browser:

     Ext.define('AM.controller.Users', {
         init: function() {
             this.listen({
                 global: {               // Global events are always fired
                     idle: this.onIdle   // from the same object, so there
                 }                       // are no selectors
             });
         }
     });

As this relates to components, the following example:

     Ext.define('AM.controller.Users', {
         init: function() {
             this.listen({
                 component: {
                     'useredit button[action=save]': {
                        click: this.updateUser
                     }
                 }
             });
         },
         ...
     });

Is equivalent to:

     Ext.define('AM.controller.Users', {
         init: function() {
             this.control({
                 'useredit button[action=save]': {
                    click: this.updateUser
                 }
             });
         },
         ...
     });

Of course, these can all be combined in a single call and used instead of
`control`, like so:

     Ext.define('AM.controller.Users', {
         init: function() {
             this.listen({
                 global: {
                     idle: this.onIdle
                 },
                 controller: {
                     '*': {
                        foobar: this.onAnyFooBar
                     },
                     '#foo': {
                        bar: this.onFooBar
                     }
                 },
                 component: {
                     'useredit button[action=save]': {
                        click: this.updateUser
                     }
                 },
                 store: {
                     '#qux': {
                         load: this.onQuxLoad
                     }
                 }
             });
         },
         ...
     });

This class manages a formula defined for an `{@link Ext.app.ViewModel}`.

## Formula Basics

Formulas in a `ViewModel` can be defined as simply as just a function:

     formulas: {
         xy: function (get) { return get('x') * get('y'); }
     }

When you need to be more explicit, "xy" can become an object. The following means the
same thing as above:

     formulas: {
         xy: {
             get: function (get) { return get('x') * get('y'); }
         }
     }

### Data Dependencies

One of the important aspects of a `ViewModel` is notification of change. In order to
manage this, a `ViewModel` *must* know the dependencies between data. In the above case
this is accomplished by **parsing the text of the function**. While this is convenient
and reduces the maintenance/risk that would come from explicitly listing dependencies
separately, there are some rules to be aware of:

  * All dependencies are resolved by matching the binding statements in the getter function.
  * If you need to use these values in other ways, cache them as a `var` (following
    the first rule to capture the value) and use that `var`.

In the above formulas, the "xy" formula depends on "x" and "y" in the `ViewModel`. As
these values change, the formula is called to produce the correct value for "xy". This
in turn can be used by other formulas. For example:

     formulas: {
         xy: function (get) {  // "get" is arbitrary but a good convention
             return get('x') * get('y');
         },

         xyz: function (get) {
             return get('xy') * get('z');
         }
     }

In the above, "xyz" depends on "xy" and "z" values in the `ViewModel`.

### The Getter Method

The argument passed to the formula is a function that allows you to retrieve
the matched bind statements.

     formulas: {
         foo: function (get) {
             return get('theUser.address.city');
         }
     }

In the above, the dependency is resolved to `theUser.address.city`. The formula will not
be triggered until the value for `city` is present.

### Capturing Values

If values need to be used repeatedly, you can use a `var` as long as the Rules are not
broken.

     formulas: {
         x2y2: function (get) {
             // These are still "visible" as "get('x')" and "get('y')" so this is OK:
             var x = get('x'),
                 y = get('y');

             return x * x * y * y;
         }
     }

## Explicit Binding

While function parsing is convenient, there are times it is not the best solution. In
these cases, an explicit `{@link #cfg!bind bind}` can be given. To revisit the previous example with an
explicit binding:

     formulas: {
         zip: {
             bind: '{foo.bar.zip}',

             get: function (zip) {
                 // NOTE: the only thing we get is what our bind produces.
                 return zip * 2;
             }
         }
     }

In this case we have given the formula an explicit `{@link #cfg!bind bind}` value so it will no longer
parse the `get` function. Instead, it will call `{@link Ext.app.ViewModel#method!bind Ext.app.ViewModel#bind}` with
the value of the `{@link #cfg!bind bind}` property and pass the produced value to `get` whenever it
changes.

## Settable Formulas

When a formula is "reversible" it can be given a `set` method to allow it to participate
in two-way binding. For example:

     formulas: {
            fullName: {
                get: function (get) {
                    var ret = get('firstName') || '';

                    if (get('lastName')) {
                        ret += ' ' +  get('lastName');
                    }

                    return ret;
                },

                set: function (value) {
                    var space = value.indexOf(' '),
                        split = (space < 0) ? value.length : space;

                    this.set({
                        firstName: value.substring(0, split),
                        lastName: value.substring(split + 1)
                    });
                }
            }
        }

When the `set` method is called the `this` reference is the `{@link Ext.app.ViewModel}` so it
just calls its `{@link Ext.app.ViewModel#method!set set method}`.

## Single Run Formulas

If a formula only needs to produce an initial value, it can be marked as `{@link #cfg!single single}`.

     formulas: {
         xy: {
             single: true,

             get: function (get) {
                 return get('x') * get('y');
             }
         }
     }

This formulas `get` method will be called with `x` and `y` once and then its binding
to these properties will be destroyed. This means the `get` method (and hence the value
of `xy`) will only be executed/calculated once.

This option tracks for static branches of the root object which can be pruned using
{@link #method!pruneStaticKeys #pruneStaticKeys}. This can be useful to only get the dynamic parts of a multi bind:

     {
         a: 1,
         b: '{someBind}',
         c: ['a', 'b', 'c'],
         d: ['a', 'b', '{someBind}'],
         e: {
             y: 1,
             z: 2
         },
         f: {
             y: 1,
             z: '{someBind}'
         }
     }

     // Will produce
     {
         b: value,
         d: ['a', 'b', value],
         f: {
             y: 1,
             z: value
         }
     }

