The 'd3-heatmap' component is used for visualizing matrices
where the individual values are represented as colors.
The component makes use of two {@link Ext.d3.axis.Data} axes (one for each
dimension of the matrix) and a single {@link Ext.d3.axis.Color} axis
to encode the values.

    @example
    Ext.create('Ext.panel.Panel', {
        renderTo: Ext.getBody(),
        title: 'Heatmap Chart',
        height: 750,
        width: 750,
        layout: 'fit',
        items: [
            {
                xtype: 'd3-heatmap',
                padding: {
                    top: 20,
                    right: 30,
                    bottom: 20,
                    left: 80
                },

                xAxis: {
                    axis: {
                        ticks: 'd3.timeDay',
                        tickFormat: "d3.timeFormat('%b %d')",
                        orient: 'bottom'
                    },
                    scale: {
                        type: 'time'
                    },
                    title: {
                        text: 'Date'
                    },
                    field: 'date',
                    step: 24 * 60 * 60 * 1000
                },

                yAxis: {
                    axis: {
                        orient: 'left',
                        tickFormat: "d3.format('$d')"
                    },
                    scale: {
                        type: 'linear'
                    },
                    title: {
                        text: 'Total'
                    },
                    field: 'bucket',
                    step: 100
                },

                colorAxis: {
                    scale: {
                        type: 'linear',
                        range: ['white', 'orange']
                    },
                    field: 'count',
                    minimum: 0
                },

