    },
    'avg...': function(args) {
        var count = 0,
            sum = 0,
            i = args.length,
            v;
        for (; i-- > 0; /* empty */
        ) {
            v = args[i];
            if (v != null) {
                sum += v;
                ++count;
            }
        }
        return count ? sum / count : 0;
    },
    date: function(arg) {
        return (arg instanceof Date) ? arg : Ext.Date.parse(arg);
    },
