        return (arg == null) ? '' : String(arg).toLowerCase();
    },
    'max...': function(args) {
        var ret = null,
            i = args.length,
            v;
        for (; i-- > 0; /* empty */
        ) {
            v = args[i];
            if (v != null) {
                ret = (ret === null) ? v : (ret < v ? v : ret);
            }
        }
        return ret;
    },
    'min...': function(args) {
        var ret = null,
            i = args.length,
            v;
        for (; i-- > 0; /* empty */
        ) {
            v = args[i];
            if (v != null) {
                ret = (ret === null) ? v : (ret < v ? ret : v);
            }
