{
    // Notes:
    // g = {Number} calculation group (0 or 1. only group 1 contributes to
    // date calculations.)
    // c = {String} calculation method (required for group 1. null for group 0.
    // {0} = currentGroup - position in regex result array)
    // s = {String} regex pattern. all matches are stored in results[], and are
    // accessible by the calculation mapped to 'c'
    d: {
        g: 1,
        c: "d = parseInt(results[{0}], 10);\n",
        s: "(3[0-1]|[1-2][0-9]|0[1-9])"
    },
    // day of month with leading zeroes (01 - 31)
    j: {
        g: 1,
        c: "d = parseInt(results[{0}], 10);\n",
        s: "(3[0-1]|[1-2][0-9]|[1-9])"
    },
    // day of month without leading zeroes (1 - 31)
    D: function() {
        var a = [],
            i;
        // get localised short day names
        for (i = 0; i < 7; i++) {
            a.push(utilDate.getShortDayName(i));
        }
        return {
            g: 0,
            c: null,
            s: "(?:" + a.join("|") + ")"
        };
    },
    l: function() {
        return {
            g: 0,
            c: null,
            s: "(?:" + utilDate.dayNames.join("|") + ")"
        };
    },
    N: {
        g: 0,
        c: null,
        s: "[1-7]"
    },
    // ISO-8601 day number (1 (monday) - 7 (sunday))
    //<locale type="object" property="parseCodes">
    S: {
        g: 0,
        c: null,
        s: "(?:st|nd|rd|th)"
    },
    //</locale>
    w: {
        g: 0,
        c: null,
        s: "[0-6]"
    },
    // JavaScript day number (0 (sunday) - 6 (saturday))
    z: {
        g: 1,
        c: "z = parseInt(results[{0}], 10);\n",
        s: "(\\d{1,3})"
    },
    // day of the year (0 - 364 (365 in leap years))
    W: {
        g: 1,
        c: "W = parseInt(results[{0}], 10);\n",
        s: "(\\d{2})"
    },
    // ISO-8601 week number (with leading zero)
    F: function() {
        return {
            g: 1,
            c: "m = parseInt(me.getMonthNumber(results[{0}]), 10);\n",
            s: "(" + utilDate.monthNames.join("|") + ")"
        };
    },
    M: function() {
        var a = [],
            i;
        // get localised short month names
        for (i = 0; i < 12; i++) {
            a.push(utilDate.getShortMonthName(i));
        }
        return Ext.applyIf({
            s: "(" + a.join("|") + ")"
        }, utilDate.formatCodeToRegex("F"));
    },
    m: {
        g: 1,
        c: "m = parseInt(results[{0}], 10) - 1;\n",
        s: "(1[0-2]|0[1-9])"
    },
    // month number with leading zeros (01 - 12)
    n: {
        g: 1,
        c: "m = parseInt(results[{0}], 10) - 1;\n",
        s: "(1[0-2]|[1-9])"
    },
    // month number without leading zeros (1 - 12)
    t: {
        g: 0,
        c: null,
        s: "(?:\\d{2})"
    },
    // no. of days in the month (28 - 31)
    L: {
        g: 0,
        c: null,
        s: "(?:1|0)"
    },
    o: {
        g: 1,
        c: "y = parseInt(results[{0}], 10);\n",
        s: "(\\d{4})"
    },
    // ISO-8601 year number (with leading zero)
    Y: {
        g: 1,
        c: "y = parseInt(results[{0}], 10);\n",
        s: "(\\d{4})"
    },
    // 4-digit year
    y: {
        g: 1,
        c: "var ty = parseInt(results[{0}], 10);\n" + "y = ty > me.y2kYear ? 1900 + ty : 2000 + ty;\n",
        // 2-digit year
        s: "(\\d{2})"
    },
    // In the am/pm parsing routines, we allow both upper and lower case
    // even though it doesn't exactly match the spec. It gives much more flexibility
    // in being able to specify case insensitive regexes.
    /* eslint-disable indent */
    //<locale type="object" property="parseCodes">
    a: {
        g: 1,
        c: "if (/(am)/i.test(results[{0}])) {\n" + "if (!h || h == 12) { h = 0; }\n" + "} else { if (!h || h < 12) { h = (h || 0) + 12; }}",
        s: "(am|pm|AM|PM)",
        calcAtEnd: true
    },
    //</locale>
    //<locale type="object" property="parseCodes">
    A: {
        g: 1,
        c: "if (/(am)/i.test(results[{0}])) {\n" + "if (!h || h == 12) { h = 0; }\n" + "} else { if (!h || h < 12) { h = (h || 0) + 12; }}",
        s: "(AM|PM|am|pm)",
        calcAtEnd: true
    },
    //</locale>
    g: {
        g: 1,
        c: "h = parseInt(results[{0}], 10);\n",
        s: "(1[0-2]|[1-9])"
    },
    //  12-hr format of an hour without leading zeroes (1 - 12)
    G: {
        g: 1,
        c: "h = parseInt(results[{0}], 10);\n",
        s: "(2[0-3]|1[0-9]|[0-9])"
    },
    // 24-hr format of an hour without leading zeroes (0 - 23)
    h: {
        g: 1,
        c: "h = parseInt(results[{0}], 10);\n",
        s: "(1[0-2]|0[1-9])"
    },
    //  12-hr format of an hour with leading zeroes (01 - 12)
    H: {
        g: 1,
        c: "h = parseInt(results[{0}], 10);\n",
        s: "(2[0-3]|[0-1][0-9])"
    },
    //  24-hr format of an hour with leading zeroes (00 - 23)
    i: {
        g: 1,
        c: "i = parseInt(results[{0}], 10);\n",
        s: "([0-5][0-9])"
    },
    // minutes with leading zeros (00 - 59)
    s: {
        g: 1,
        c: "s = parseInt(results[{0}], 10);\n",
        s: "([0-5][0-9])"
    },
    // seconds with leading zeros (00 - 59)
    u: {
        g: 1,
        c: "ms = results[{0}]; ms = parseInt(ms, 10)/Math.pow(10, ms.length - 3);\n",
        s: "(\\d+)"
    },
    // decimal fraction of a second (minimum = 1 digit, maximum = unlimited)
    /* eslint-disable max-len */
    O: {
        g: 1,
        c: [
            "o = results[{0}];",
            "var sn = o.substring(0,1),",
            // get + / - sign
            "hr = o.substring(1,3)*1 + Math.floor(o.substring(3,5) / 60),",
            // get hours (performs minutes-to-hour conversion also, just in case)
            "mn = o.substring(3,5) % 60;",
            // get minutes
            "o = ((-12 <= (hr*60 + mn)/60) && ((hr*60 + mn)/60 <= 14))? (sn + Ext.String.leftPad(hr, 2, '0') + Ext.String.leftPad(mn, 2, '0')) : null;\n"
        ].join(// -12hrs <= GMT offset <= 14hrs
        "\n"),
        s: "([+-]\\d{4})"
    },
    // GMT offset in hrs and mins
    P: {
        g: 1,
        c: [
            "o = results[{0}];",
            "var sn = o.substring(0,1),",
            // get + / - sign
            "hr = o.substring(1,3)*1 + Math.floor(o.substring(4,6) / 60),",
            // get hours (performs minutes-to-hour conversion also, just in case)
            "mn = o.substring(4,6) % 60;",
            // get minutes
            "o = ((-12 <= (hr*60 + mn)/60) && ((hr*60 + mn)/60 <= 14))? (sn + Ext.String.leftPad(hr, 2, '0') + Ext.String.leftPad(mn, 2, '0')) : null;\n"
        ].join(// -12hrs <= GMT offset <= 14hrs
        "\n"),
        s: "([+-]\\d{2}:\\d{2})"
    },
    // GMT offset in hrs and mins (with colon separator)
    T: {
        g: 0,
        c: null,
        s: "[A-Z]{1,5}"
    },
    // timezone abbrev. may be between 1 - 5 chars
    Z: {
        g: 1,
        c: "zz = results[{0}] * 1;\n" + // -43200 <= UTC offset <= 50400
        "zz = (-43200 <= zz && zz <= 50400)? zz : null;\n",
        s: "([+-]?\\d{1,5})"
    },
    // leading '+' sign is optional for UTC offset
    c: function() {
        var calc = [],
            arr = [
                utilDate.formatCodeToRegex("Y", 1),
                // year
                utilDate.formatCodeToRegex("m", 2),
                // month
                utilDate.formatCodeToRegex("d", 3),
                // day
                utilDate.formatCodeToRegex("H", 4),
                // hour
                utilDate.formatCodeToRegex("i", 5),
                // minute
                utilDate.formatCodeToRegex("s", 6),
                // second
                {
                    c: "ms = results[7] || '0'; ms = parseInt(ms, 10)/Math.pow(10, ms.length - 3);\n"
                },
                // decimal fraction of a second (minimum = 1 digit, maximum = unlimited)
                {
                    c: [
                        // allow either "Z" (i.e. UTC) or "-0530" or "+08:00" (i.e. UTC offset) timezone delimiters. assumes local timezone if no timezone is specified
                        "if (results[8]) {",
                        // timezone specified
                        "if (results[8] == 'Z') {",
                        "zz = 0;",
                        // UTC
                        "}",
                        "else if (results[8].indexOf(':') > -1) {",
                        utilDate.formatCodeToRegex("P", 8).c,
                        // timezone offset with colon separator
                        "}",
                        "else {",
                        utilDate.formatCodeToRegex("O", 8).c,
                        // timezone offset without colon separator
                        "}",
                        "}"
                    ].join('\n')
                }
            ],
            i, l;
        for (i = 0 , l = arr.length; i < l; ++i) {
            calc.push(arr[i].c);
        }
        return {
            g: 1,
            c: calc.join(""),
            s: [
                arr[0].s,
                // year (required)
                "(?:",
                "-",
                arr[1].s,
                // month (optional)
                "(?:",
                "-",
                arr[2].s,
                // day (optional)
                "(?:",
                "(?:T| )?",
                // time delimiter -- either a "T" or a single blank space
                arr[3].s,
                ":",
                arr[4].s,
                // hour AND minute, delimited by a single colon (optional). MUST be preceded by either a "T" or a single blank space
                "(?::",
                arr[5].s,
                ")?",
                // seconds (optional)
                "(?:(?:\\.|,)(\\d+))?",
                // decimal fraction of a second (e.g. ",12345" or ".98765") (optional)
                "(Z|(?:[-+]\\d{2}(?::)?\\d{2}))?",
                // "Z" (UTC) or "-0530" (UTC offset without colon delimiter) or "+08:00" (UTC offset with colon delimiter) (optional)
                ")?",
                ")?",
                ")?"
            ].join("")
        };
    },
    U: {
        g: 1,
        c: "u = parseInt(results[{0}], 10);\n",
        s: "(-?\\d+)"
    }
}

{
    "MS": function(input, strict) {
        // note: the timezone offset is ignored since the MS Ajax server sends
        // a UTC milliseconds-since-Unix-epoch value (negative values are allowed)
        var r = (input || '').match(MSFormatRe);
        return r ? new nativeDate(((r[1] || '') + r[2]) * 1) : null;
    },
    "time": function(input, strict) {
        var num = parseInt(input, 10);
        if (num || num === 0) {
            return new nativeDate(num);
        }
        return null;
    },
    "timestamp": function(input, strict) {
        var num = parseInt(input, 10);
        if (num || num === 0) {
            return new nativeDate(num * 1000);
        }
        return null;
    }
}

items.text:
In a few words, a Decorator is a Component that wraps around another Component. A typical
example of a Decorator is a {@link Ext.field.Field}. A form field is nothing more than a
decorator around another component, and gives the component a label, as well as extra styling
to make it look good in a form.

A Decorator can be thought of as a lightweight Container that has only one child item, and no
layout overhead. The look and feel of decorators can be styled purely in CSS.

Another powerful feature that Decorator provides is config proxying. For example: all config
items of a {@link Ext.slider.Slider} also exist in a
{@link Ext.field.Slider} for API convenience. The
{@link Ext.field.Slider} simply proxies all corresponding getters and setters to
the actual {@link Ext.slider.Slider} instance. Writing out all the setters and getters to
do that is a tedious task and a waste of code space. Instead, when you sub-class Ext.Decorator,
all you need to do is to specify those config items that you want to proxy to the Component
using a special 'proxyConfig' class property. Here's how it may look like in a Slider Field
class:

    Ext.define('My.field.Slider', {
        extend: 'Ext.Decorator',

        config: {
            component: {
                xtype: 'slider'
            }
        },

        proxyConfig: {
            minValue: 0,
            maxValue: 100,
            increment: 1
        }

        // ...
    });

Once `My.field.Slider` class is created, it will have all setters and getters methods for all
items listed in `proxyConfig` automatically generated. These methods all proxy to the same
method names that exist within the Component instance.

Deferreds are the mechanism used to create new Promises. A Deferred has a single
associated Promise that can be safely returned to external consumers to ensure they do
not interfere with the resolution or rejection of the deferred operation.

This implementation of Promises is an extension of the ECMAScript 6 Promises API as
detailed [here][1]. For a compatible, though less full featured, API see `{@link Ext.Promise}`.

A Deferred is typically used within the body of a function that performs an asynchronous
operation. When that operation succeeds, the Deferred should be resolved; if that
operation fails, the Deferred should be rejected.

Each Deferred has an associated Promise. A Promise delegates `{@link #method!then then}` calls to its
Deferred's `{@link #method!then then}` method. In this way, access to Deferred operations are divided between
producer (Deferred) and consumer (Promise) roles.

## Basic Usage

In it's most common form, a method will create and return a Promise like this:

     // A method in a service class which uses a Store and returns a Promise
     //
     loadCompanies: function () {
         var deferred = new Ext.Deferred(); // create the Ext.Deferred object

         this.companyStore.load({
             callback: function (records, operation, success) {
                 if (success) {
                     // Use "deferred" to drive the promise:
                     deferred.resolve(records);
                 }
                 else {
                     // Use "deferred" to drive the promise:
                     deferred.reject("Error loading Companies.");
                 }
             }
         });

         return deferred.promise;  // return the Promise to the caller
     }

You can see this method first creates a `{@link Ext.Deferred}` object. It then
returns its `Promise` object for use by the caller. Finally, in the asynchronous
callback, it resolves the `deferred` object if the call was successful, and rejects the
`deferred` if the call failed.

When a Deferred's `{@link #method!resolve resolve}` method is called, it fulfills with the optionally specified
value. If `{@link #method!resolve resolve}` is called with a then-able (i.e.a Function or Object with a `{@link #method!then then}`
function, such as another Promise) it assimilates the then-able's result; the Deferred
provides its own `{@link #method!resolve resolve}` and `{@link #method!reject reject}` methods as the onFulfilled or onRejected
arguments in a call to that then-able's `{@link #method!then then}` function. If an error is thrown while
calling the then-able's `{@link #method!then then}` function (prior to any call back to the specified
`{@link #method!resolve resolve}` or `{@link #method!reject reject}` methods), the Deferred rejects with that error. If a Deferred's
`{@link #method!resolve resolve}` method is called with its own Promise, it rejects with a TypeError.

When a Deferred's `{@link #method!reject reject}` method is called, it rejects with the optionally specified
reason.

Each time a Deferred's `{@link #method!then then}` method is called, it captures a pair of optional
onFulfilled and onRejected callbacks and returns a Promise of the Deferred's future
value as transformed by those callbacks.

See `{@link Ext.promise.Promise}` for an example of using the returned Promise.

Enables or disables bordering on this component.
The following values are accepted:

- `null` or `true (default): Do nothing and allow the border to be specified
by the theme.
- `false`: suppress the default border provided by the theme.

Please note that enabling bordering via this config will not add a `border-color`
or `border-style` CSS property to the component; you provide the `border-color`
and `border-style` via CSS rule or {@link #cfg!style #style} configuration
(if not already provide by the theme).

## Using {@link #cfg!style #style}:

    Ext.Viewport.add({
        centered: true,
        width: 100,
        height: 100,

        style: 'border: 1px solid blue;'
        // ...
    });

## Using CSS:

    Ext.Viewport.add({
        centered: true,
        width: 100,
        height: 100,

        cls: 'my-component'
        // ...
    });

And your CSS file:

    .my-component {
        border: 1px solid red;
    }

