        storeId:'employeeStore',
        fields:['firstname', 'lastname', 'seniority', 'department'],
        groupField: 'department',
        data:[
            { firstname: "Michael",
              lastname: "Scott",
              seniority: 7,
              department: "Management"
            },
            { firstname: "Dwight",
              lastname: "Schrute",
              seniority: 2,
              department: "Sales"
            },
            { firstname: "Jim",
              lastname: "Halpert",
              seniority: 3,
              department: "Sales"
            },
            { firstname: "Kevin",
