            align: 'right',
            action: 'submit'
        }
    ]
}

items.text:
This plugin allows grid data export using various exporters. Each exporter should extend
the {@link Ext.exporter.Base} class.

Two new methods are created on the grid panel by this plugin:

 - saveDocumentAs(config): saves the document
 - getDocumentData(config): returns the document content

The grid data is exported for all grid columns that have the flag
{@link Ext.grid.column.Column#cfg!ignoreExport ignoreExport} as false.

If the grid store is grouped and you want the export to group your results
then use the following properties in the config object sent to the `{@link #method!saveDocumentAs saveDocumentAs}` function:

- includeGroups: set to true to include the groups
- includeSummary: set to true to include also group/grand summaries if proper `summaryType`
was defined on columns

During data export the data for each column could be formatted in multiple ways:

- using the {@link Ext.grid.column.Column#cfg!exportStyle exportStyle} format
- using the {@link Ext.grid.column.Column#cfg!formatter formatter} if no `exportStyle` is defined
- using the {@link Ext.grid.column.Column#cfg!exportRenderer exportRenderer}

If `exportStyle.format`, `formatter` and `exportRenderer` are all defined on a column
then the `exportStyle.format` wins and will be used to format the data for that column.

Example usage:

     {
         xtype: 'grid',
         plugins: {
             gridexporter: true
         },
         columns: [{
             dataIndex: 'value',
             text: 'Total',
             exportStyle: {
                 format: 'Currency',
                 alignment: {
                     horizontal: 'Right'
                 }
             }
         }]
     }

     grid.saveDocumentAs({
         type: 'xlsx',
         title: 'My export',
         fileName: 'myExport.xlsx'
     });

The Paging Toolbar is a specialized toolbar that is
bound to a `{@link Ext.data.Store}` and provides automatic paging control.

    @example
    var store = Ext.create('Ext.data.Store', {
        fields: ['fname', 'lname', 'talent'],
        pageSize: 3,
        data: [
            { 'fname': 'Barry',  'lname': 'Allen',      'talent': 'Speedster' },
            { 'fname': 'Oliver', 'lname': 'Queen',      'talent': 'Archery'  },
            { 'fname': 'Kara',   'lname': 'Zor-El',     'talent': 'All'  },
            { 'fname': 'Helena', 'lname': 'Bertinelli', 'talent': 'Weapons Expert'  },
            { 'fname': 'Hal',    'lname': 'Jordan',     'talent': 'Willpower'  },
        ]
    });

    Ext.create('Ext.grid.Grid', {
        title: 'DC Personnel',

        store: store,
        plugins: {
            pagingtoolbar: true
        },

        columns: [
            { text: 'First Name', dataIndex: 'fname',  flex: 1 },
            { text: 'Last Name',  dataIndex: 'lname',  flex: 1 },
            { text: 'Talent',     dataIndex: 'talent', flex: 1 }
        ],

        height: 230,
        layout: 'fit',
        fullscreen: true
    });

This plugin provides row drag and drop functionality.

    @example
    var store = Ext.create('Ext.data.Store', {
        fields: ['name', 'email', 'phone'],
        data: [
            { name: 'Lisa', email: 'lisa@simpsons.com', phone: '555-111-1224' },
            { name: 'Bart', email: 'bart@simpsons.com', phone: '555-222-1234' },
            { name: 'Homer', email: 'homer@simpsons.com', phone: '555-222-1244' },
            { name: 'Marge', email: 'marge@simpsons.com', phone: '555-222-1254' }
        ],
        proxy: {
            type: 'memory',
            reader: {
                 type: 'json'
            }
        }
    });

    Ext.create('Ext.grid.Grid', {
        store: store,
        columns: [{
            header: 'Name',
            dataIndex: 'name'
        }, {
           text: 'Email',
           dataIndex: 'email',
           width: 230
      }, {
           text: 'Phone',
           dataIndex: 'phone',
           width: 150
      }],
       plugins: {
            gridrowdragdrop: {
               dragText: 'Drag and drop to reorganize'
            }
       },
        height: 300,
        fullscreen: true
    });

**This event is fired on valid drop at {@link Ext.grid.Grid}**

Returning `false` to this event cancels drop operation and prevent drop event.

    grid.on('beforedrop', function(node, data, overModel, dropPosition) {
         // return false;
    });

The Row Expander plugin provides an "expander" column to give the user the ability to show
or hide the {@link Ext.grid.Row#cfg!body} of each row.

    @example
    var store = Ext.create('Ext.data.Store', {
        fields: ['fname', 'lname', 'talent', 'powers'],
        groupField: 'powers',
        data: [
            { 'fname': 'Barry',
              'lname': 'Allen',
              'talent': 'Speedster',
              'powers': true
            },
            { 'fname': 'Oliver',
              'lname': 'Queen',
              'talent': 'Archery',
              'powers': false
            },
            { 'fname': 'Kara',
              'lname': 'Zor-El',
              'talent': 'All',
              'powers': true
            },
            { 'fname': 'Helena',
              'lname': 'Bertinelli',
              'talent': 'Weapons Expert',
              'powers': false
            },
            { 'fname': 'Hal',
              'lname': 'Jordan',
              'talent': 'Willpower',
              'powers': true
            },
        ]
    });

    Ext.create('Ext.grid.Grid', {
        title: 'DC Personnel',
        grouped: true,
        store: store,
        plugins: {
            rowexpander: true
        },
        itemConfig: {
            body: {
                tpl: '<img height="100" src="http://www.sencha.com/assets/images/sencha-avatar-64x64.png"/>'
            }
        },
        columns: [
            { text: 'First Name', dataIndex: 'fname',  flex: 1 },
            { text: 'Last Name',  dataIndex: 'lname',  flex: 1 },
            { text: 'Talent',     dataIndex: 'talent', flex: 1 },
            { text: 'Powers?',    dataIndex: 'powers', flex: 1 }
        ],
        height: 400,
        layout: 'fit',
        fullscreen: true
    });

The RowOperations plugin enables user to select rows in a {@link Ext.grid.Grid} and
then perform an operation (e.g. Delete) on them. This plugin adds a "Select" button
to the grid's title to start the selection process. This button is replaced by "Done"
while in selection mode. When selecting an extra `{@link #cfg!operation operation}` button is displayed. By
default this button can be used to delete records.

In addition, this plugin will ensure that the {@link Ext.grid.Grid#cfg!selectable}
selection method is enabled. The {@link #cfg!selectionColumn #selectionColumn} config of this plugin can be
used to control this configuration.

Customizing the RowOperations plugin to provide operations other then "Delete" can
be done with the `{@link #cfg!operation operation}` config:

     Ext.create({
         xtype: 'grid',
         fullscreen: true,

         title: 'My Grid',

         plugins: {
             rowoperations: {
                 operation: {
                     text: 'Archive',
                     handler: 'onRowOperation',
                     ui: 'alt'
                 }
             }
         },

         store: store

         columns: [
             // columns
         ]
     });

Since the `{@link #cfg!operation operation}` is a {@link Ext.Button}, multiple operations can easily be
provided using the button's  {@link Ext.Button#cfg!menu}.

This {@link Ext.grid.Grid} plugin manages a bottom-docked summary {@link #cfg!row row}.

By default, the column's {@link Ext.grid.column.Column#cfg!dataIndex} is used
to read from the {@link Ext.data.Store#method!getSummaryRecord summary record} as controlled by
the model's {@link Ext.data.Model#cfg!summary} definition. To use a different
field, the {@link Ext.grid.column.Column#cfg!summaryDataIndex} can be
specified.

The {@link Ext.grid.column.Column#cfg!summary} config can be used to perform
column-specific summarization. The `summary` config uses one of the registered summary
types (see below). Custom summary types can be defined, or a column-specific algorithm
can be provided with a {@link Ext.grid.column.Column#cfg!summaryRenderer}.

## Summary Types

The `summary` type can be one of the predefined summary types:

+ {@link Ext.data.summary.Average}
+ {@link Ext.data.summary.Count}
+ {@link Ext.data.summary.Max}
+ {@link Ext.data.summary.Min}
+ {@link Ext.data.summary.Sum}


    @example
    var store = Ext.create('Ext.data.Store', {
        fields: ['fname', 'lname', 'talent', 'wins'],
        data: [
            { 'fname': 'Barry',  'lname': 'Allen', 'talent': 'Speedster', 'wins': 150  },
            { 'fname': 'Oliver', 'lname': 'Queen', 'talent': 'Archery', 'wins': 27  },
            { 'fname': 'Kara',   'lname': 'Zor-El', 'talent': 'All', 'wins': 75  },
            { 'fname': 'Helena', 'lname': 'Bertinelli', 'talent': 'Weapons Expert', 'wins': 7  },
            { 'fname': 'Hal',    'lname': 'Jordan', 'talent': 'Willpower', 'wins': 198  },
        ]
    });

    Ext.create('Ext.grid.Grid', {
        title: 'DC Personnel',

        store: store,
        plugins: {
            gridsummaryrow: true
        },
        columns: [
            { text: 'First Name', dataIndex: 'fname',  flex: 1 },
            { text: 'Last Name',  dataIndex: 'lname',  flex: 1 },
            { text: 'Talent',     dataIndex: 'talent', flex: 1 },
            { text: 'Wins',       dataIndex: 'wins',   flex: 1,  summary: 'sum' }
        ],
        fullscreen: true,
        height:275
    });

This plugin provides drag and drop node moving in a tree.

    @example
    var ts = Ext.create('Ext.data.TreeStore', {
        root: {
            text: 'Genre',
            expanded: true,
            children: [
                {
                    text: 'Comedy',
                    children: [
