        filterType: {
            bind: {
                bindTo: '{form.filter.type}',
                deep: true
            },
            get: function(record) {
                return record && record.isModel ? record.get('value') : record;
            }
        },
        filterOperator: {
            bind: {
                bindTo: '{form.filter.operator}',
                deep: true
            },
            get: function(record) {
                return record && record.isModel ? record.get('value') : record;
            }
        },
        filterOperatorValue: {
            // eslint-disable-next-line max-len
            bind: '{filterCommon && !(filterOperator === "between" || filterOperator === "not between")}',
            get: function(v) {
                return v;
            }
        },
        filterOperatorBetween: {
            // eslint-disable-next-line max-len
            bind: '{filterCommon && (filterOperator === "between" || filterOperator === "not between")}',
            get: function(v) {
                return v;
            }
        },
        filterCommon: {
            bind: '{filterType === "label" || filterType === "value"}',
            get: function(v) {
                return v;
            }
        },
        filterLabel: {
            bind: '{filterType === "label"}',
            get: function(v) {
                return v;
            }
        },
        filterValue: {
            bind: '{filterType === "value"}',
            get: function(v) {
                return v;
            }
        },
        filterTop10: {
            bind: '{filterType === "top10"}',
            get: function(v) {
                return v;
            }
        }
    }
}

